    "article": "60",
    "article_display": "Art. 60",
    "speech_number": "Artigo 60 do Estatuto da Criança e do Adolescente",
    "title": "Da Idade Mínima para o Trabalho e Contrato de Aprendizagem",
    "hierarchy": {
      "title_num": "Livro I - Título II: Do Direito à Profissionalização e Proteção no Trabalho",
      "chapter_num": "Proibição de Trabalho até 14 Anos, Contrato de Aprendizagem (14 a 24 Anos) e Vedação de Trabalho Noturno/Insalubre"
    },
    "category": "Direitos Fundamentais",
    "isOabFocus": true,
    "source": {
      "name": "Presidência da República - Planalto",
      "url": "https://www.planalto.gov.br/ccivil_03/leis/l8069.htm#art60",
      "last_checked_at": "2026-08-15T00:00:00Z",
      "version": "1.0.0"
    },
    "official_text": "Art. 60. É proibido qualquer trabalho a menores de quatorze anos de idade, salvo na condição de aprendiz.\nArt. 67. Ao adolescente empregado, aprendiz, em regime familiar de trabalho, aluno de escola técnica, assistido em entidade governamental ou não-governamental, é vedado trabalho:\nI - noturno, realizado entre as vinte e duas horas de um dia e as cinco horas do dia seguinte;\nII - perigoso, insalubre ou penoso;\nIII - realizado em locais prejudiciais à sua formação e ao seu desenvolvimento físico, psíquico, moral e social;\nIV - realizado em horários e locais que não permitam a freqüência à escola.",
    "content": [
      {
        "id": "eca-art60-caput",
        "type": "caput",
        "text": "Art. 60. É proibido qualquer trabalho a menores de quatorze anos de idade, salvo na condição de aprendiz.\nArt. 67. Ao adolescente empregado, aprendiz, em regime familiar de trabalho, aluno de escola técnica, assistido em entidade governamental ou não-governamental, é vedado trabalho:\nI - noturno, realizado entre as vinte e duas horas de um dia e as cinco horas do dia seguinte;\nII - perigoso, insalubre ou penoso;\nIII - realizado em locais prejudiciais à sua formação e ao seu desenvolvimento físico, psíquico, moral e social;\nIV - realizado em horários e locais que não permitam a freqüência à escola.",
        "speechText": "Art. 60. É proibido qualquer trabalho a menores de quatorze anos de idade, salvo na condição de aprendiz. Art. 67. Ao adolescente empregado, aprendiz, em regime familiar de trabalho, aluno de escola técnica, assistido em entidade governamental ou não-governamental, é vedado trabalho: I - noturno, realizado entre as vinte e duas horas de um dia e as cinco horas do dia seguinte; II - perigoso, insalubre ou penoso; III - realizado em locais prejudiciais à sua formação e ao seu desenvolvimento físico, psíquico, moral e social; IV - realizado em horários e locais que não permitam a freqüência à escola."
      }
    ],
    "professor_mode": {
      "simple_explanation": "Regime constitucional do trabalho infantil: proibição total de trabalho até 13 anos; de 14 a 15 anos permite-se EXCLUSIVAMENTE aprendizagem; de 16 a 17 anos permite-se trabalho regular com vedações expressas (noturno, perigoso, insalubre ou prejudicial à escola).",
      "summary": "Proibido trabalho a menores de 14 anos (salvo aprendiz a partir de 14); vedado trabalho noturno, insalubre ou perigoso aos menores de 18.",
      "practical_example": "Aplicação prática do Art. 60: aplicação cogente na atuação perante as Varas da Infância e Juventude, Conselho Tutelar e Ministério Público.",
      "exam_tip": "Atenção: O Art. 60 possui altíssima incidência nas provas da OAB e concursos da Magistratura, Ministério Público e Defensoria Pública.",
      "legal_terms": [
        "ECA",
        "Direitos Fundamentais",
        "Proteção Integral",
        "Infância e Juventude"
      ],
      "speechText": "Modo Professor sobre o Artigo 60 do Estatuto da Criança e do Adolescente: Regime constitucional do trabalho infantil: proibição total de trabalho até 13 anos; de 14 a 15 anos permite-se EXCLUSIVAMENTE aprendizagem; de 16 a 17 anos permite-se trabalho regular com vedações expressas (noturno, perigoso, insalubre ou prejudicial à escola)."
    }
